import { useState } from "react";
import { Link, useNavigate, useSearchParams } from "react-router-dom";
import { useTranslation } from "react-i18next";
import { Check, Eye, EyeOff, Lock, Mail, Phone, ShieldCheck, Sparkles, Star, Truck, User } from "lucide-react";
import { BackButton } from "../components/BackButton";
import { useShop } from "../lib/store";
import { cn } from "../lib/ui";
export const AuthPage = () => {
  const { t } = useTranslation();
  const navigate = useNavigate();
  const [params] = useSearchParams();
  const { user, login, register, logout } = useShop();
  const [mode, setMode] = useState(params.get("mode") === "register" ? "register" : "login");
  const [name, setName] = useState("");
  const [phone, setPhone] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [confirm, setConfirm] = useState("");
  const [showPass, setShowPass] = useState(false);
  const [errors, setErrors] = useState({});
  if (user) {
    return <div className="container-page py-16">
        <div className="animate-fade-up card mx-auto flex max-w-md flex-col items-center p-8 text-center">
          <span className="relative">
            <span className="absolute inset-0 rounded-full bg-brand-500/30 blur-lg" />
            <span className="accent-bg relative flex h-16 w-16 items-center justify-center rounded-full text-white shadow-glow"><Check size={30} /></span>
          </span>
          <h1 className="mt-5 font-display text-2xl font-extrabold">{t("loginTitle")}, <span className="text-gradient">{user.name.split(" ")[0]}</span>!</h1>
          <p className="mt-1 text-sm text-[var(--muted)]">{user.phone}</p>
          <div className="mt-6 flex w-full flex-col gap-2.5">
            <Link to="/profile" className="btn-primary">{t("profile")}</Link>
            <Link to="/orders" className="btn-secondary">{t("myOrders")}</Link>
            <button onClick={logout} className="btn-ghost text-rose-500">{t("logOut")}</button>
          </div>
        </div>
      </div>;
  }
  const submit = (e) => {
    e.preventDefault();
    const errs = {};
    if (mode === "register" && !name.trim()) errs.name = "Ismingizni kiriting";
    if (phone.replace(/\D/g, "").length < 9) errs.phone = "Telefon raqamni to'g'ri kiriting";
    if (mode === "register" && !email.includes("@")) errs.email = "Email manzilni to'g'ri kiriting";
    if (password.length < 4) errs.password = "Parol kamida 4 ta belgidan iborat bo'lsin";
    if (mode === "register" && password !== confirm) errs.confirm = "Parollar mos kelmadi";
    setErrors(errs);
    if (Object.keys(errs).length > 0) return;
    if (mode === "login") {
      login(phone, name || "Aziz Karimov");
      navigate("/profile");
    } else {
      register(name, phone, email);
      navigate("/profile");
    }
  };
  const demo = () => {
    login("+998 90 123 45 67", "Aziz Karimov");
    navigate("/profile");
  };
  return <div className="container-page py-5 sm:py-8">
      <div className="mb-5">
        <BackButton to="/" />
      </div>

      {
    /* brand hero line */
  }
      <div className="mb-6 animate-fade-up">
        <span className="badge border border-brand-500/25 bg-brand-500/10 text-brand-700 dark:text-brand-300"><Sparkles size={11} className="text-brand-500" /> MaxSHOP Plus</span>
        <h1 className="mt-3.5 font-display text-[32px] font-extrabold leading-[1.08] tracking-tight">
          Max<br /><span className="text-gradient">SHOP Market</span>
        </h1>
      </div>

      <div className="grid gap-5 lg:grid-cols-[1fr_1.05fr] lg:items-start">
        {
    /* benefits column */
  }
        <div className="stagger space-y-3 lg:pt-2">
          <div className="card overflow-hidden p-0">
            <div className="accent-bg relative p-6 text-white">
              <span className="pointer-events-none absolute -right-12 -top-12 h-40 w-40 rounded-full bg-white/20 blur-2xl" />
              <h2 className="relative font-display text-xl font-extrabold leading-snug">{t("authTitle")}</h2>
              <p className="relative mt-2 text-xs text-white/85">{t("authSubtitle")}</p>
            </div>
            <div className="stagger grid gap-3 p-5 sm:grid-cols-1">
              {[
    { icon: Truck, text: t("freeDeliveryNote") },
    { icon: Star, text: t("freshQualityTitle") },
    { icon: ShieldCheck, text: t("securePayment2") }
  ].map((b) => <div key={b.text} className="card-soft flex items-center gap-3 p-3">
                  <span className="accent-bg flex h-10 w-10 shrink-0 items-center justify-center rounded-2xl text-white shadow-glow"><b.icon size={17} /></span>
                  <p className="text-[11px] font-bold leading-snug">{b.text}</p>
                </div>)}
            </div>
            <div className="mx-5 mb-5 rounded-2xl border border-amber-300/40 bg-amber-400/10 p-4">
              <div className="flex items-center gap-0.5">{[1, 2, 3, 4, 5].map((i) => <Star key={i} size={12} className="fill-amber-400 text-amber-400" />)}</div>
              <p className="mt-2 text-[11px] font-medium leading-relaxed text-[var(--text)]">"MaxSHOP bilan xarid qilish juda qulay. Har doim yangi mahsulotlar va tez yetkazish."</p>
              <p className="mt-2 text-[10px] font-extrabold text-[var(--muted)]">Dilnoza R. · Toshkent</p>
            </div>
          </div>
        </div>

        {
    /* form card */
  }
        <div className="card animate-fade-up p-5 shadow-soft sm:p-7">
          <div className="flex rounded-2xl border bg-[var(--surface-2)] p-1.5">
            <button onClick={() => {
    setMode("login");
    setErrors({});
  }} className={cn("flex-1 rounded-xl py-2.5 text-xs font-extrabold transition", mode === "login" ? "accent-bg text-white shadow-glow" : "text-[var(--muted)]")}>{t("login")}</button>
            <button onClick={() => {
    setMode("register");
    setErrors({});
  }} className={cn("flex-1 rounded-xl py-2.5 text-xs font-extrabold transition", mode === "register" ? "accent-bg text-white shadow-glow" : "text-[var(--muted)]")}>{t("register")}</button>
          </div>

          <h2 className="mt-5 font-display text-xl font-extrabold tracking-tight">{mode === "login" ? t("loginTitle") : t("registerTitle")}</h2>
          <p className="mt-1 text-xs text-[var(--muted)]">{mode === "login" ? t("loginSubtitle") : t("registerSubtitle")}</p>

          <form onSubmit={submit} className="mt-5 space-y-3.5">
            {mode === "register" && <div>
                <label className="label">{t("fullName")}</label>
                <div className="relative">
                  <User size={15} className="absolute left-3.5 top-1/2 -translate-y-1/2 text-[var(--muted)]" />
                  <input value={name} onChange={(e) => setName(e.target.value)} className={cn("input pl-10 pr-3", errors.name && "border-rose-400")} placeholder="Aziz Karimov" />
                </div>
                {errors.name && <p className="mt-1 text-[10px] font-bold text-rose-500">{errors.name}</p>}
              </div>}
            <div>
              <label className="label">{t("phone")}</label>
              <div className="relative">
                <Phone size={15} className="absolute left-3.5 top-1/2 -translate-y-1/2 text-[var(--muted)]" />
                <input value={phone} onChange={(e) => setPhone(e.target.value)} className={cn("input pl-10 pr-3", errors.phone && "border-rose-400")} placeholder="+998 90 123 45 67" />
              </div>
              {errors.phone && <p className="mt-1 text-[10px] font-bold text-rose-500">{errors.phone}</p>}
            </div>
            {mode === "register" && <div>
                <label className="label">{t("email")}</label>
                <div className="relative">
                  <Mail size={15} className="absolute left-3.5 top-1/2 -translate-y-1/2 text-[var(--muted)]" />
                  <input value={email} onChange={(e) => setEmail(e.target.value)} className={cn("input pl-10 pr-3", errors.email && "border-rose-400")} placeholder="aziz@mail.uz" />
                </div>
                {errors.email && <p className="mt-1 text-[10px] font-bold text-rose-500">{errors.email}</p>}
              </div>}
            <div>
              <label className="label">{t("password")}</label>
              <div className="relative">
                <Lock size={15} className="absolute left-3.5 top-1/2 -translate-y-1/2 text-[var(--muted)]" />
                <input type={showPass ? "text" : "password"} value={password} onChange={(e) => setPassword(e.target.value)} className={cn("input pl-10 pr-11", errors.password && "border-rose-400")} placeholder="••••••••" />
                <button type="button" onClick={() => setShowPass((v) => !v)} className="absolute right-3.5 top-1/2 -translate-y-1/2 text-[var(--muted)] transition hover:text-brand-600">{showPass ? <EyeOff size={15} /> : <Eye size={15} />}</button>
              </div>
              {errors.password && <p className="mt-1 text-[10px] font-bold text-rose-500">{errors.password}</p>}
            </div>
            {mode === "register" && <div>
                <label className="label">{t("confirmPassword")}</label>
                <div className="relative">
                  <Lock size={15} className="absolute left-3.5 top-1/2 -translate-y-1/2 text-[var(--muted)]" />
                  <input type="password" value={confirm} onChange={(e) => setConfirm(e.target.value)} className={cn("input pl-10 pr-3", errors.confirm && "border-rose-400")} placeholder="••••••••" />
                </div>
                {errors.confirm && <p className="mt-1 text-[10px] font-bold text-rose-500">{errors.confirm}</p>}
              </div>}
            <p className="rounded-2xl border border-brand-400/30 bg-brand-500/5 p-3 text-[10px] font-semibold text-[var(--muted)]">🔒 {t("otpNote")}</p>
            <button type="submit" className="btn-primary w-full">{mode === "login" ? t("loginBtn") : t("registerBtn")} →</button>
          </form>

          <div className="my-4 flex items-center gap-2 text-[10px] font-extrabold uppercase tracking-wider text-[var(--muted)]"><span className="h-px flex-1 bg-[var(--border)]" /> yoki <span className="h-px flex-1 bg-[var(--border)]" /></div>
          <button onClick={demo} className="btn-secondary w-full text-xs"><Sparkles size={14} className="text-brand-600 dark:text-brand-400" /> {t("demoLogin")}</button>

          <p className="mt-4 text-center text-[11px] font-semibold text-[var(--muted)]">
            {mode === "login" ? t("noAccount") : t("haveAccount")}{" "}
            <button onClick={() => setMode(mode === "login" ? "register" : "login")} className="font-extrabold text-gradient">
              {mode === "login" ? t("register") : t("login")}
            </button>
          </p>
        </div>
      </div>
    </div>;
};
